package com.example.agenticai.tool; import org.springframework.stereotype.Component; import java.util.*; @Component public class McpToolRegistry {private final Map<String,McpTool> tools=new LinkedHashMap<>(); public McpToolRegistry(List<McpTool> list){list.forEach(t->tools.put(t.name(),t));} public McpTool get(String n){return tools.get(n);} public Collection<McpTool> all(){return tools.values();}}
